# -*- coding: utf-8 -*-
"""Lote 2 · parte C (cirugía general: trauma, vía biliar, ano, shock hemorrágico)."""
from lote02b import Q, L, SAB, SCH

Q(a="cirugia", cat=None, tema="Clase de shock hemorrágico (ATLS)", año=2016, ext=False,
  e="Varón de 30 años, politraumatizado por accidente de tránsito, es evaluado en emergencia. Examen: ansioso, confuso, pálido, pulso mayor de 120 por minuto, hipotenso, FR 30-40 por minuto y diuresis de 5-15 mL/h. Abdomen distendido y doloroso; se sospecha hemoperitoneo. ¿Qué clase de shock hemorrágico presenta?",
  o=["IV.", "I.", "II.", "III.", "V."], k="D",
  c="La clasificación de ATLS del shock hemorrágico asigna cuatro clases. Clase I: pérdida < 15 % (< 750 mL), sin cambios. Clase II: 15-30 %, taquicardia de 100-120, ansiedad y presión de pulso disminuida. Clase III: 31-40 % (1500-2000 mL), FC 120-140, hipotensión, FR 30-40, diuresis 5-15 mL/h y estado confuso o ansioso. Clase IV: más del 40 %, FC > 140, hipotensión marcada, anuria y letargo o coma. Este paciente (confuso, FC > 120, FR 30-40, diuresis 5-15 mL/h, hipotenso) tiene clase III. El tratamiento es hemostasia quirúrgica o por embolización más reposición con hemoderivados en proporción 1:1:1 (protocolo de transfusión masiva), ácido tranexámico en las primeras 3 horas y evitar la hipotermia. La reposición excesiva con cristaloides empeora la coagulopatía.",
  f="ATLS, 11.ª ed. (2025); WSES, hemorragia en trauma; Guía europea de sangrado y coagulopatía en trauma (2023)")

Q(a="cirugia", cat=None, tema="Trauma cerrado con peritonitis generalizada", año=2016, ext=False,
  e="Varón de 24 años, que hace 3 horas sufre accidente de tránsito. Hemodinámicamente estable. Refiere dolor abdominal y náuseas. Examen: dolor abdominal en epigastrio con contractura y reacción peritoneal generalizada. Leucocitos 18 000 por mm³. ¿Cuál es el órgano lesionado?",
  o=["Intestino delgado.", "Hígado.", "Bazo.", "Riñón.", "Páncreas."], k="A",
  c="En el trauma abdominal cerrado, un paciente hemodinámicamente estable con peritonitis generalizada y leucocitosis tiene una lesión de víscera hueca (intestino delgado o colon): el contenido intestinal produce irritación peritoneal química y bacteriana, mientras que las lesiones de órganos sólidos (hígado, bazo) se manifiestan sobre todo por hemorragia, con taquicardia, hipotensión y dolor del hombro o abdomen, y solo desarrollan peritonitis cuando hay hemoperitoneo masivo. El riñón y el páncreas son retroperitoneales; el páncreas da dolor epigástrico, hiperamilasemia y signos tardíos. El mecanismo típico de lesión del intestino es la compresión por el cinturón de seguridad. La TC con contraste, el aire libre y la peritonitis orientan; la laparotomía o la laparoscopía confirman y se repara o reseca.",
  f="WSES, trauma abdominal cerrado (2017); ATLS, 11.ª ed. (2025); " + SCH)

Q(a="cirugia", cat=None, tema="Causa más frecuente de obstrucción en países no industrializados", año=2016, ext=False,
  e="¿Cuál es la causa más frecuente de obstrucción intestinal en pacientes no operados en países no industrializados?",
  o=["Hernias.", "Vólvulo.", "Neoplasias.", "Íleo biliar.", "Malformación intestinal."], k="A",
  c="En el paciente sin cirugía abdominal previa, la causa más frecuente de obstrucción del intestino delgado es la hernia de la pared abdominal complicada, tanto en países industrializados como en países en vías de desarrollo, donde además las hernias llegan tarde a consulta (acceso limitado a la cirugía electiva) y la incidencia de estrangulación es mayor. En esas regiones se agregan el vólvulo de sigmoides y la obstrucción por Ascaris lumbricoides (masa de áscaris en niños). En el mundo industrializado dominan las adherencias posoperatorias. La mortalidad de la hernia estrangulada con resección intestinal supera el 10 %. Programas de cirugía herniaria electiva salvan vidas.",
  f="WSES, hernias complicadas y obstrucción (2018); " + SAB)

Q(a="cirugia", cat=None, tema="Localización más frecuente de la angiodisplasia", año=2016, ext=False,
  e="¿En cuál de los siguientes segmentos digestivos se localiza con mayor frecuencia la angiodisplasia vascular?",
  o=["Colon ascendente.", "Colon descendente.", "Íleon terminal.", "Sigmoides.", "Recto."], k="A",
  c="La angiodisplasia (malformación vascular adquirida de la mucosa) se localiza con mayor frecuencia en el ciego y el colon ascendente, y en pacientes mayores de 60 años; se asocia a estenosis aórtica (síndrome de Heyde, por pérdida de multímeros del factor de von Willebrand), insuficiencia renal crónica y uso de anticoagulantes. Causa sangrado digestivo bajo intermitente, indoloro y a veces anemia ferropénica crónica. Diagnóstico: colonoscopía (lesión roja en «helecho»), cápsula endoscópica si es de intestino delgado y angiografía en sangrado activo. Tratamiento: coagulación con argón, tratamiento endoscópico y, en recurrencia, octreótido o talidomida; cirugía como último recurso. El divertículo es la causa más frecuente de sangrado digestivo bajo masivo.",
  f="ACG, hemorragia digestiva baja (2023); ASGE, hemorragia digestiva (2023); " + SAB)

Q(a="cirugia", cat=None, tema="Localización más frecuente de los linfomas digestivos", año=2016, ext=False,
  e="¿Cuál es la localización más frecuente de los linfomas en el aparato digestivo?",
  o=["Estómago.", "Apéndice cecal.", "Duodeno.", "Colon derecho.", "Colon izquierdo."], k="A",
  c="El tubo digestivo es el sitio extraganglionar más frecuente de los linfomas no Hodgkin, y dentro de él el estómago es el más afectado (50-60 %), seguido del intestino delgado (íleon) y el colon. El linfoma gástrico más frecuente es el difuso de células B grandes, y el linfoma MALT, de bajo grado, se asocia a Helicobacter pylori: la erradicación (triple o cuádruple terapia) lo cura en el 75 % de los casos si no se disemina. El diagnóstico es endoscópico con biopsia múltiple. En el niño, el íleon terminal (linfoma de Burkitt) puede debutar como intususcepción. La enfermedad celíaca se asocia con el linfoma T asociado a enteropatía.",
  f="ESMO, linfomas gástricos MALT (2013) y linfoma difuso de células B grandes (2015); " + SAB)

Q(a="cirugia", cat=None, tema="Lesión de la vía biliar con sección total del colédoco", año=2016, ext=False,
  e="Durante una colecistectomía laparoscópica a un hombre de 40 años por colelitiasis, antes de concluir la cirugía se percata la presencia de bilis en el campo operatorio. Al revisar se encuentra sección total del colédoco que mide 8 mm de diámetro, razón por la que se convierte la cirugía y se decide reparar la vía biliar. ¿Cuál de las siguientes alternativas quirúrgicas es la más apropiada?",
  o=["Hepatoyeyunoanastomosis en Y de Roux término-lateral.", "Colédoco-duodenoanastomosis término-lateral.", "Colédoco-duodenoanastomosis látero-lateral.", "Reparación del colédoco más dren de Kehr.", "Colédoco-gastroanastomosis."], k="A",
  c="La lesión de la vía biliar ocurre en 0,3-0,5 % de las colecistectomías laparoscópicas; el factor de riesgo es no lograr la «visión crítica de seguridad» (identificar solo dos estructuras que entran a la vesícula). Si se reconoce durante la cirugía y hay sección completa, con pérdida de tejido o ducto de menos de 3-4 mm, la reparación estándar es la hepaticoyeyunostomía en Y de Roux término-lateral (anastomosis mucosa a mucosa, con puntos separados de material absorbible, sin tensión ni isquemia), preferiblemente por un cirujano hepatobiliar, con colangiografía previa y drenaje. La anastomosis término-terminal con sonda en T solo si el ducto es de buen calibre, con mínima pérdida de tejido y sin isquemia (hasta 50 % de estenosis tardía). Las derivaciones al duodeno o al estómago no son de elección por el reflujo.",
  f="Clasificación de Strasberg; SAGES, visión crítica de seguridad (2017); Guías de Tokio 2018 (TG18)")

Q(a="cirugia", cat=None, tema="Clasificación de Todani de los quistes de colédoco", año=2016, ext=False,
  e="De acuerdo a la clasificación de Todani para quistes de colédoco, ¿cuál es el tipo más frecuente?",
  o=["I.", "II.", "III.", "IV.", "V."], k="A",
  c="La clasificación de Todani describe cinco tipos de quistes de la vía biliar: I, dilatación fusiforme o sacular del colédoco (80-90 %); II, divertículo; III, coledococele (dilatación intraduodenal); IV, quistes múltiples (IVa intra y extrahepáticos, IVb solo extrahepáticos); V, enfermedad de Caroli (quistes intrahepáticos). Son más frecuentes en mujeres y en poblaciones asiáticas, se asocian a unión pancreatobiliar anómala y tienen un riesgo de colangiocarcinoma del 10-30 % en la edad adulta. La presentación clásica es la tríada de dolor abdominal, ictericia y masa palpable, aunque solo se ve en el 20 %. El tratamiento es la resección completa del quiste con hepaticoyeyunostomía en Y de Roux.",
  f="Clasificación de Todani (1977, revisada en 2003); " + SAB)

Q(a="cirugia", cat=None, tema="Hernia inguinal indirecta: relación con los vasos epigástricos", año=2017, ext=False,
  e="Paciente acude con dolor abdominal, náuseas y vómitos de contenido fecaloideo. Examen: masa inguinal derecha no reductible compatible con hernia, por lo que el paciente es operado. Usted diagnostica hernia inguinal indirecta. ¿Qué caracteriza a este tipo de hernia?",
  o=["Se ubica lateral a los vasos epigástricos inferiores.", "Protruye por la pared posterior del conducto inguinal.", "Pasa a través del conducto femoral.", "Medial a los vasos epigástricos inferiores.", "Es más frecuente en mujeres."], k="A",
  c="La hernia inguinal indirecta sale por el anillo inguinal profundo, lateral a los vasos epigásticos inferiores, recorre el conducto inguinal dentro del cordón espermático (cubierta por el cremáster) y puede llegar al escroto. Es la más frecuente en ambos sexos (alrededor de dos tercios) y suele ser congénita, por persistencia del conducto peritoneo-vaginal. La hernia directa es medial a los epigástricos, protruye por la pared posterior (triángulo de Hesselbach) y es adquirida por debilidad de la fascia transversalis. La femoral pasa por debajo del ligamento inguinal. La hernia inguinal es 8-10 veces más frecuente en varones, pero la femoral es más común en mujeres. El enunciado describe una hernia complicada con obstrucción: requiere cirugía urgente.",
  f="EHS, guías de hernia de la ingle (2018); " + SAB)

Q(a="cirugia", cat=None, tema="Lesión de páncreas por trauma cerrado: peritonitis tardía", año=2017, ext=False,
  e="Varón de 20 años que tuvo traumatismo abdominal contuso (rodillazo en el abdomen). 48 horas después presenta temperatura de 39 °C y dolor abdominal. Examen: reacción peritoneal, leucocitosis de 21 000 por mm³. ¿Cuál es el órgano lesionado?",
  o=["Páncreas.", "Riñón.", "Hígado.", "Mesenterio.", "Bazo."], k="A",
  c="Un golpe directo, localizado y de baja energía en el epigastrio (rodillazo, manubrio de bicicleta) comprime el páncreas y el duodeno contra la columna: puede producir contusión o rotura pancreática con fuga de enzimas, que se expresa horas o días después con dolor, fiebre, íleo, peritonitis y elevación de amilasa y lipasa. La lesión es retroperitoneal y de síntomas tardíos, por lo que se pasa por alto con facilidad. El hígado y el bazo se manifiestan sobre todo por hemorragia y shock; el riñón, por hematuria y dolor lumbar; el mesenterio, por hemoperitoneo o isquemia del asa. La TC con contraste puede ser normal en las primeras horas; la colangiopancreatografía por resonancia evalúa el conducto pancreático. Lesiones con rotura ductal requieren cirugía.",
  f="WSES, trauma pancreático (2019); EAST, trauma pancreático; " + SCH)

Q(a="cirugia", cat=None, tema="Metástasis inguinal de carcinoma escamoso", año=2017, ext=False,
  e="Varón de 63 años con pérdida de peso y astenia. Examen: tumoración inguinal izquierda de 1,5 × 1,5 cm, dura, poco móvil. Biopsia: carcinoma de células escamosas. ¿Cuál es el origen primario del tumor?",
  o=["Ano.", "Recto.", "Próstata.", "Sigmoides.", "Testículo."], k="A",
  c="Los ganglios inguinales reciben drenaje linfático de la piel de miembros inferiores y periné, del pene, la vulva, el canal anal (por debajo de la línea dentada) y el escroto. Una metástasis inguinal de carcinoma escamoso orienta a un primario cutáneo, de pene, vulva o canal anal; entre las opciones, el carcinoma escamoso del canal anal. El recto, la próstata y el sigmoides son adenocarcinomas con drenaje a ganglios ilíacos y mesentéricos, y el testículo drena a los ganglios retroperitoneales (paraaórticos) y sus tumores son de células germinales. El carcinoma anal asociado a VPH 16 se trata con quimiorradioterapia (esquema de Nigro: mitomicina y 5-fluorouracilo), no con cirugía. En el paciente con VIH o inmunodeprimido el tamizaje con citología anal es recomendable.",
  f="NCCN, cáncer anal (2025); ESMO, cáncer anal (2021); " + SAB)

Q(a="cirugia", cat=None, tema="Úlcera perforada: radiografía de pie", año=2017, ext=False,
  e="Varón de 60 años, con tratamiento irregular por úlcera péptica, ingresa por emergencia presentando dolor abdominal intenso de inicio súbito hace 1 hora. Examen: PA 100/70 mmHg, pulso 100 por minuto, abdomen con dolor difuso y resistente, ruidos hidroaéreos ausentes, signo de rebote positivo. ¿Qué solicita para llegar al diagnóstico inicial?",
  o=["Rx de tórax y abdomen de pie.", "Ecografía abdominal.", "Hemograma.", "Rx de abdomen en decúbito.", "Dosaje de amilasa y lipasa."], k="A",
  c="Un paciente con úlcera péptica y dolor epigástrico súbito, intenso, con abdomen en tabla, rebote y ausencia de ruidos hidroaéreos tiene una úlcera perforada. La radiografía de tórax de pie (o abdomen de pie) muestra neumoperitoneo (aire libre bajo el diafragma, signo de la media luna) en el 70-80 % y es la prueba inicial más rápida y barata; si es dudosa y el paciente está estable, la TC detecta cantidades pequeñas de aire y la localización de la perforación. El tratamiento es quirúrgico: cierre primario con parche de epiplón (Graham), con biopsia si es úlcera gástrica, lavado y erradicación de H. pylori; en pacientes de muy alto riesgo, manejo no operatorio con antibióticos e inhibidores de bomba. La amilasa puede estar levemente elevada, sin definir el diagnóstico.",
  f="WSES, úlcera péptica perforada (2020); " + SAB)

Q(a="cirugia", cat=None, tema="Colangitis aguda en la diabética: drenaje biliar", año=2017, ext=False,
  e="Diabética de 45 años en tratamiento irregular, hace 4 días presenta dolor abdominal en cuadrante superior derecho, sensación de alza térmica y coloración amarillenta en piel y mucosas. Examen: ictericia, PA 90/60 mmHg, pulso 110 por minuto, T 39 °C. Abdomen doloroso en cuadrante superior derecho, Blumberg negativo, Murphy positivo. Ecografía: colelitiasis y coledocolitiasis. ¿Cuál es la conducta terapéutica a seguir?",
  o=["Colangiopancreatografía retrógrada endoscópica.", "Colecistectomía abierta.", "Exploración de vías biliares.", "Colecistostomía abierta.", "Derivación biliodigestiva."], k="A",
  c="La tríada de Charcot (fiebre, ictericia y dolor en hipocondrio derecho) con hipotensión indica colangitis aguda grave (Guías de Tokio 2018, grado III por disfunción cardiovascular). Los pilares son la reanimación, los antibióticos de amplio espectro (piperacilina-tazobactam o cefalosporina más metronidazol) y el drenaje urgente de la vía biliar obstruida, de elección por CPRE con esfinterotomía y extracción del cálculo o colocación de un stent o sonda nasobiliar. La cirugía abierta tiene mortalidad alta en el paciente séptico y se reserva si fracasa el drenaje endoscópico o percutáneo. La colecistectomía se realiza después, en el mismo ingreso, cuando se resuelve la sepsis. El diabético requiere control de glucemia.",
  f="Guías de Tokio 2018 (TG18); ASGE, coledocolitiasis (2019); Surviving Sepsis Campaign (2021)")

Q(a="cirugia", cat=None, tema="Estudio inicial de las enfermedades de la vía biliar", año=2017, ext=False,
  e="¿Cuál es el procedimiento más utilizado en la actualidad, por su alta sensibilidad, en el diagnóstico inicial de las enfermedades del tracto biliar?",
  o=["Ultrasonografía abdominal.", "Colecistografía oral.", "Tomografía axial computarizada.", "Colangiopancreatografía retrógrada endoscópica.", "Colangiografía transparietohepática."], k="A",
  c="La ecografía abdominal es el estudio inicial de la vía biliar: no es invasiva, no irradia, es barata y tiene sensibilidad del 95 % para la litiasis vesicular; muestra pared engrosada, líquido perivesicular, signo de Murphy ecográfico y dilatación de la vía biliar (colédoco > 6-7 mm), aunque detecta mal los cálculos del colédoco distal (sensibilidad ~ 40 %). Si hay sospecha de coledocolitiasis, se completa con colangiorresonancia o ecoendoscopía, y la CPRE queda como procedimiento terapéutico. La colecistografía oral y la colangiografía transparietohepática están prácticamente en desuso. La TC es útil en complicaciones y tumores, pero no es de primera línea.",
  f="ASGE, coledocolitiasis (2019); ACR, criterios de adecuación (dolor en hipocondrio derecho); " + SAB)

Q(a="cirugia", cat=None, tema="Síndrome de dumping posgastrectomía", año=2017, ext=False,
  e="Varón de 40 años portador de una úlcera gástrica maligna en la región antral. Es sometido a una gastrectomía subtotal Billroth II. Hace aproximadamente dos semanas, luego de 2 horas de la ingesta de alimentos presenta epigastralgia seguida de náuseas, vómitos y diarrea explosiva, que se acompañan de palpitaciones, taquicardia y diaforesis. ¿Cuál sería la primera posibilidad diagnóstica?",
  o=["Síndrome de vaciamiento rápido.", "Gastritis alcalina.", "Úlcera gástrica de neoboca.", "Obstrucción del asa eferente.", "Hiperacidez gástrica."], k="A",
  c="El síndrome de dumping aparece tras gastrectomías o cirugía bariátrica, por el vaciamiento rápido de alimentos hiperosmolares al intestino delgado. El dumping precoz (10-30 minutos) causa dolor, diarrea, náuseas y síntomas vasomotores (palpitaciones, sudor, hipotensión) por desplazamiento de líquido y liberación de péptidos intestinales. El tardío (1-3 horas) se debe a hipoglucemia reactiva por exceso de insulina. Se trata con comidas pequeñas y frecuentes, evitar azúcares simples, líquidos entre comidas, fibra (pectina) y, en casos refractarios, acarbosa u octreótido. La gastritis alcalina produce dolor y vómitos biliosos que no mejoran con la comida; la obstrucción del asa aferente, dolor posprandial con vómito explosivo bilioso y distensión.",
  f=SAB + "; " + SCH + "; AGA, cirugía bariátrica y complicaciones")

Q(a="pediatria", cat=None, tema="Malformación anorrectal más frecuente en varones", año=2017, ext=False,
  e="¿Cuál es la malformación anorrectal más frecuente en varones?",
  o=["Fístula rectovesical.", "Fístula rectouretral prostática.", "Fístula rectouretral bulbar.", "Fístula cutánea perineal.", "Ano imperforado sin fístula."], k="C",
  c="Las malformaciones anorrectales se clasifican según la fístula (Pena). En varones, la forma más frecuente es la fístula rectouretral (bulbar la más común), seguida de la fístula perineal (cutánea) y la prostática; la rectovesical es rara. En niñas, la forma más frecuente es la fístula rectovestibular. El 50-60 % se asocia a otras anomalías (síndrome VACTERL: vertebrales, anales, cardiacas, traqueoesofágicas, renales y de extremidades), por eso se estudia con ecografía renal, ecocardiograma y radiografía de columna. El diagnóstico es clínico (examen perineal), con meconio por la orina en las fístulas urinarias. Las formas bajas (fístula perineal) se corrigen con anoplastía en el periodo neonatal; las altas, con colostomía descompresiva y anorrectoplastia sagital posterior (Peña) a los 2-3 meses.",
  f="Nelson Tratado de Pediatría 22.ª ed.; Sociedad Europea de Cirugía Pediátrica (EUPSA), malformaciones anorrectales; Pena y de Vries (2017)")

Q(a="cirugia", cat=None, tema="Apendicitis con Alvarado intermedio: imagen", año=2017, ext=False,
  e="Mujer de 26 años, presenta hace 24 horas dolor abdominal en epigastrio que se irradia a las 3 horas a fosa ilíaca derecha, acompañado de náuseas sin vómitos. Examen: PA 100/60 mmHg, pulso 100 por minuto, T 38,5 °C. Abdomen doloroso en fosa ilíaca derecha, McBurney positivo. Hemograma normal. Según la escala de Alvarado, ¿cuál es la conducta a seguir?",
  o=["Tomografía helicoidal multicorte.", "Observación y hemograma de control.", "Analgésicos y control ambulatorio.", "Apendicectomía.", "Laparotomía exploratoria."], k="A",
  c="La escala de Alvarado (MANTRELS) suma: dolor en fosa ilíaca derecha (2), migración del dolor (1), anorexia (1), náuseas o vómitos (1), Blumberg (1), temperatura > 37,3 °C (1), leucocitosis > 10 000 (2) y desviación izquierda (1). Esta paciente tiene dolor en FID (2), migración (1), náuseas (1) y fiebre (1), con hemograma normal: 5 puntos, probabilidad intermedia. Con 5-6 puntos se indica un estudio de imagen: ecografía (primero en mujeres jóvenes y niños) o TC con contraste; con 0-4 se observa, y con 7-10 se opera. En mujeres en edad fértil, la imagen ayuda a descartar patología ginecológica (quiste, torsión, EPI, embarazo ectópico). La apendicectomía sin imagen en un Alvarado intermedio da más apéndices normales.",
  f="WSES, apendicitis aguda (2020); " + SAB)

Q(a="cirugia", cat=None, tema="Tramadol y convulsiones", año=2017, ext=False,
  e="Varón de 30 años en el posoperatorio de colecistectomía refiere dolor intenso en la herida operatoria, recibiendo un analgésico. Dos horas después cursa con convulsiones tónico-clónicas generalizadas. ¿Qué analgésico se relaciona con dicho efecto secundario?",
  o=["Tramadol.", "Meloxicam.", "Ketorolaco.", "Paracetamol.", "Celecoxib."], k="A",
  c="El tramadol es un analgésico opioide débil, agonista del receptor mu, que además inhibe la recaptación de serotonina y noradrenalina. Esta doble acción reduce el umbral convulsivo, y puede producir crisis tonicoclónicas, sobre todo con dosis altas, insuficiencia renal o hepática, antecedente de epilepsia o uso con antidepresivos ISRS, tricíclicos o IMAO (también síndrome serotoninérgico). Otros efectos adversos: náuseas, mareos, estreñimiento, depresión respiratoria y dependencia. Los AINE (ketorolaco, meloxicam, celecoxib) producen gastropatía, sangrado, nefrotoxicidad y riesgo cardiovascular, pero no convulsiones; el paracetamol, hepatotoxicidad en sobredosis. Se trata la crisis con benzodiazepinas y se suspende el fármaco; la naloxona no revierte bien las convulsiones del tramadol.",
  f="PROSPECT, analgesia en colecistectomía laparoscópica (2020); Katzung Farmacología Básica y Clínica 15.ª ed.; OMS, escalera analgésica")

Q(a="cirugia", cat=None, tema="Localización de la fisura anal crónica", año=2017, ext=False,
  e="¿En qué línea del canal anal se ubica con más frecuencia la fisura anal crónica?",
  o=["Media posterior.", "Lateral derecha.", "Media anterior.", "Dentada.", "Lateral izquierda."], k="A",
  c="La fisura anal es una ulceración longitudinal del anodermo distal a la línea dentada; en más del 90 % se ubica en la línea media posterior, porque allí la irrigación es más pobre (la arteria rectal inferior da menos ramas) y el esfínter anal interno hipertónico ejerce más tensión. Una fisura lateral o múltiple sugiere enfermedad de Crohn, tuberculosis, sífilis, VIH, leucemia o cáncer. Clínica: dolor intenso al defecar con sangrado escaso rojo brillante; la crónica (más de 6-8 semanas) tiene un colgajo centinela, una papila hipertrófica y fibras del esfínter interno visibles. Tratamiento: fibra y baños de asiento; nifedipino o diltiazem tópico; toxina botulínica; esfinterotomía lateral interna si falla, con una tasa de curación cercana al 95 %.",
  f="ASCRS, fisura anal (2017, actualización 2023); " + SAB)

Q(a="ciencias_basicas", cat="Anatomía", tema="Cabeza del páncreas en el marco duodenal", año=2017, ext=False,
  e="¿Qué porción del páncreas está dentro de la concavidad en forma de C del duodeno?",
  o=["Cabeza.", "Cuerpo.", "Cuello.", "Cola.", "Proceso unciforme."], k="A",
  c="El páncreas es un órgano retroperitoneal con cabeza, cuello, cuerpo y cola. La cabeza ocupa la concavidad del marco duodenal (en C) a la derecha de la línea media, a la altura de L2, y contiene el conducto pancreático principal y la parte intrapancreática del colédoco; por esa razón, un tumor de la cabeza produce ictericia obstructiva indolora con vesícula palpable (signo de Courvoisier-Terrier). El proceso unciforme es una prolongación de la cabeza hacia atrás y a la izquierda, detrás de la vena mesentérica superior; el cuello está delante de la confluencia mesentérica-portal y el cuerpo cruza la aorta y la arteria mesentérica superior. La cola llega al hilio esplénico: el trauma esplénico puede lesionarla. La irrigación proviene de la arteria esplénica y de las pancreatoduodenales.",
  f="Moore Anatomía con orientación clínica 8.ª ed.; Netter Atlas de Anatomía Humana 8.ª ed.")

Q(a="pediatria", cat=None, tema="Estenosis hipertrófica del píloro: piloromiotomía", año=2018, ext=False,
  e="Recién nacido de 4 semanas con vómitos en «proyectil»; le diagnostican estenosis hipertrófica del píloro. ¿Cuál es el tratamiento quirúrgico de elección?",
  o=["Piloromiotomía laparoscópica.", "Esofagostomía.", "Gastroduodenoanastomosis.", "Gastrectomía distal.", "Gastrostomía."], k="A",
  c="La estenosis hipertrófica del píloro aparece entre las 2 y 8 semanas de vida, con vómitos no biliosos «en proyectil» después de cada toma, el lactante con hambre voraz, pérdida de peso, deshidratación y alcalosis metabólica hipoclorémica con hipopotasemia. A la exploración se palpa la «oliva pilórica» y se observan ondas peristálticas. La ecografía confirma: grosor muscular ≥ 3-4 mm y longitud del canal pilórico ≥ 15-17 mm. Primero se corrige el desequilibrio hidroelectrolítico (solución salina con dextrosa y potasio) y luego se hace la piloromiotomía extramucosa de Fredet-Ramstedt, por vía abierta o laparoscópica, con alimentación precoz y curación definitiva. Más frecuente en varones primogénitos; se asocia al uso de eritromicina en las primeras semanas.",
  f="Nelson Tratado de Pediatría 22.ª ed.; Sociedad Británica de Cirugía Pediátrica; " + SCH)

Q(a="cirugia", cat=None, tema="Ictericia litiásica: estudio de la vía biliar", año=2018, ext=False,
  e="Mujer de 40 años, desde hace tres días con ictericia leve, sin fiebre, dolor tipo cólico en hipocondrio derecho. Antecedente de colecistitis crónica. Examen: ictericia de piel y escleras. Abdomen distendido y doloroso a la palpación profunda en hipocondrio derecho. ¿Cuál es el examen indicado para su diagnóstico?",
  o=["Tomografía abdominal.", "Ecografía endoscópica.", "Colangiografía endoscópica.", "Colecistografía endovenosa.", "Ecografía abdominal."], k="C",
  c="La ictericia en una paciente con litiasis vesicular es coledocolitiasis hasta que se demuestre lo contrario. Las guías ASGE 2019 estratifican la probabilidad: alta (cálculo en la imagen, colangitis o bilirrubina > 4 mg/dL con colédoco dilatado) lleva directo a CPRE terapéutica; intermedia (alteración de pruebas hepáticas, colédoco dilatado o edad > 55) requiere confirmar con ecoendoscopía o colangiorresonancia, y baja, colecistectomía con colangiografía intraoperatoria. En este caso la clave del libro es la colangiografía endoscópica, que diagnostica y trata en el mismo acto; la colangiorresonancia es el método no invasivo de elección cuando solo se busca confirmar el cálculo, y la ecografía abdominal es el estudio inicial, con baja sensibilidad para el cálculo coledociano.",
  f="ASGE, coledocolitiasis (2019); ESGE, cálculos de la vía biliar (2019); Guías de Tokio 2018 (TG18)",
  nota="Pregunta de elección discutible entre colangiografía endoscópica (clave del libro), ecoendoscopía y colangiorresonancia.")

Q(a="cirugia", cat=None, tema="Fisura anal crónica: esfinterotomía lateral interna", año=2018, ext=False,
  e="Varón de 26 años, desde hace 2 meses con diagnóstico de fisura anal no complicada y tratamiento con ablandadores de heces. La sintomatología dolorosa continúa. ¿Qué tratamiento le recomendaría?",
  o=["Esfinterotomía lateral interna.", "Esfinterotomía lateral externa.", "Anestésicos locales.", "Infiltración con toxina botulínica.", "Fisurotomía."], k="A",
  c="La fisura anal se vuelve crónica cuando dura más de 6-8 semanas: aparecen el colgajo centinela, la papila hipertrófica y la exposición de las fibras del esfínter interno. El tratamiento médico inicial (fibra, baños de asiento, nifedipino o diltiazem tópico al 2 %, con o sin lidocaína) cura el 50-65 %; cuando persiste, la esfinterotomía lateral interna es la operación de elección (curación del 95 %, menos recidiva que la dilatación), con un 5-10 % de incontinencia leve a gases. La toxina botulínica es una alternativa en pacientes con riesgo de incontinencia (mujeres multíparas, ancianos). La esfinterotomía lateral externa no se hace por el riesgo de incontinencia. Siempre buscar causas secundarias si la fisura es lateral.",
  f="ASCRS, fisura anal (2017, actualización 2023); " + SAB,
  nota="El libro no incluye el tratamiento tópico con calcioantagonistas como opción; la esfinterotomía es la clave del libro.")

Q(a="cirugia", cat=None, tema="Hemorroides internas de tercer grado (variante)", año=2018, ext=False,
  e="Mujer de 56 años, con estreñimiento crónico y tumoración sangrante que protruye por el margen anal al defecar, que ella reduce manualmente. Examen anal: tumoración blanda suprapectínea que protruye en el cuadrante anterior derecho. Se diagnostica hemorroides internas. ¿A qué grado corresponde?",
  o=["II.", "IV.", "V.", "I.", "III."], k="E",
  c="Las hemorroides internas nacen por encima de la línea pectínea (dentada), están cubiertas de mucosa y se clasifican según el prolapso: I, sangran pero no protruyen; II, prolapsan al defecar y se reducen solas; III, prolapsan y requieren reducción manual; IV, prolapso irreductible. La paciente que reduce el prolapso con la mano tiene grado III. La mayoría de las hemorroides se ubica en las posiciones 3, 7 y 11 horas (lateral izquierda, posterolateral derecha y anterolateral derecha), porque coinciden con las ramas de la arteria hemorroidal superior. Se tratan con medidas dietéticas, ligadura con banda elástica o cirugía (hemorroidectomía o hemorroidopexia) si fracasa. La rectorragia en una mujer de 56 años exige colonoscopía previa.",
  f="ASCRS, hemorroides (2018); " + SAB)

Q(a="cirugia", cat=None, tema="Causa más frecuente del síndrome compartimental", año=2018, ext=False,
  e="En un politraumatizado con fracturas en miembros superiores, ¿cuál es la causa más frecuente de síndrome compartimental?",
  o=["Alteración del drenaje linfático.", "Isquemia de los tejidos blandos.", "Edema muscular.", "Contractura muscular.", "Fracturas óseas."], k="C",
  c="El síndrome compartimental ocurre cuando la presión dentro de un compartimento osteofascial cerrado aumenta por encima de la presión de perfusión capilar (25-30 mmHg por debajo de la diastólica) y compromete la irrigación del músculo y el nervio. El mecanismo inicial es el edema muscular por traumatismo, reperfusión tras isquemia, hemorragia o quemaduras circunferenciales, que eleva el volumen del compartimento. Se produce más en fracturas de tibia y antebrazo, aplastamientos y yesos apretados. Clínica: dolor desproporcionado y en aumento, dolor al estiramiento pasivo, parestesias, tensión del compartimento; la palidez y la ausencia de pulso son tardías. Tratamiento: retirar vendajes, mantener la extremidad a nivel del corazón y fasciotomía urgente (menos de 6 horas).",
  f="BOAST, síndrome compartimental (2016); AAOS; ATLS, 11.ª ed. (2025)")

Q(a="cirugia", cat=None, tema="Respuesta neuroendocrina al shock", año=2018, ext=False,
  e="¿Cuál es la respuesta neuroendocrina hallada en shock?",
  o=["Descenso del estímulo adrenérgico.", "Inhibición de la liberación del péptido natriurético cerebral.", "Menor secreción pancreática de glucagón.", "Disminución de liberación de renina.", "Mayor liberación de ACTH."], k="E",
  c="Frente a un trauma grave, una cirugía mayor o un shock, el hipotálamo y el sistema nervioso simpático activan una respuesta neuroendocrina para mantener el volumen circulante y el aporte de energía: aumentan la liberación de ACTH (con cortisol alto), adrenalina y noradrenalina, glucagón, hormona del crecimiento, renina-angiotensina-aldosterona y vasopresina (ADH). El resultado es retención de sodio y agua, vasoconstricción, hiperglucemia por gluconeogénesis y resistencia a la insulina, y catabolismo proteico. Disminuyen la insulina (por las catecolaminas) y la T3. Esta respuesta es protectora al comienzo, pero si se prolonga contribuye a la inmunosupresión, el balance nitrogenado negativo y la falla orgánica; por eso la nutrición enteral precoz y el control de la glucemia son parte del tratamiento.",
  f="Guyton y Hall Tratado de Fisiología Médica 14.ª ed.; " + SCH + "; ESPEN, nutrición en el paciente crítico (2023)")
